-- Apply through Supabase migrations. RLS is intentionally enabled for every user-owned table.
create table if not exists conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references conversations(id) on delete cascade, user_id uuid not null references auth.users(id), role text not null check (role in ('user','assistant','system')), content text not null, created_at timestamptz not null default now());
create table if not exists execution_runs (id uuid primary key, user_id uuid not null references auth.users(id), conversation_id uuid references conversations(id), status text not null, mode text not null check (mode in ('simulation','real')), request text not null, outcome jsonb, created_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists tool_calls (id uuid primary key default gen_random_uuid(), execution_id uuid not null references execution_runs(id) on delete cascade, user_id uuid not null references auth.users(id), tool_id text not null, idempotency_key text not null, result jsonb, created_at timestamptz not null default now(), unique(user_id, idempotency_key));
create table if not exists memories (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), memory_type text not null check (memory_type in ('preference','project_context')), content jsonb not null, created_at timestamptz not null default now());
alter table conversations enable row level security; alter table messages enable row level security; alter table execution_runs enable row level security; alter table tool_calls enable row level security; alter table memories enable row level security;
create policy "owner isolation" on conversations using (auth.uid() = user_id); create policy "owner isolation" on messages using (auth.uid() = user_id); create policy "owner isolation" on execution_runs using (auth.uid() = user_id); create policy "owner isolation" on tool_calls using (auth.uid() = user_id); create policy "owner isolation" on memories using (auth.uid() = user_id);
